import{_ as l,o as e,c as i,am as n}from"./chunks/framework._FJXuPhs.js";const p=JSON.parse('{"title":"面试煎熬成蛋_Java基础","description":"","frontmatter":{"title":"面试煎熬成蛋_Java基础","excerpt":"面试煎熬成蛋_Java基础","date":"2024-03-09 15:11:53","updated":"2024-03-09 14:11:53"},"headers":[],"relativePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/index.md","filePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/index.md","lastUpdated":null}'),s={name:"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/index.md"};function t(o,a,r,u,c,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h3><h4 id="java-语言的特性有哪些" tabindex="-1">Java 语言的特性有哪些？ <a class="header-anchor" href="#java-语言的特性有哪些" aria-label="Permalink to &quot;Java 语言的特性有哪些？&quot;">​</a></h4><ul><li>Java 生态丰富</li><li>平台无关性</li><li>面向对象：继承、封装、多态</li></ul><h4 id="面向对象与面向过程" tabindex="-1">面向对象与面向过程 <a class="header-anchor" href="#面向对象与面向过程" aria-label="Permalink to &quot;面向对象与面向过程&quot;">​</a></h4><ul><li>面向对象 <ul><li>将具体的事务抽象，封装其中的行为方法，进行实现的一种方式</li></ul></li><li>面向过程 <ul><li>顺序执行，按照步骤处理</li></ul></li></ul><h4 id="java-的基本数据类型" tabindex="-1">Java 的基本数据类型 <a class="header-anchor" href="#java-的基本数据类型" aria-label="Permalink to &quot;Java 的基本数据类型&quot;">​</a></h4><ul><li>基本数据类型 默认占用空间 默认值 包装类型 取值范围</li><li>byte 1字节 0 Byte -128-127</li><li>char 2字节 &#39;\\u0000&#39; Character</li><li>short 2字节 0 Short</li><li>int 4字节 0 Integer</li><li>long 8字节 0L Long</li><li>float 4字节 0.0f Float</li><li>double 8 字节 0.0d Double</li><li>boolean 1字节 false Boolean</li></ul><h4 id="什么下会使用包装类-自动拆装箱了解吗-常量池技术是否清楚。" tabindex="-1">什么下会使用包装类，自动拆装箱了解吗，常量池技术是否清楚。 <a class="header-anchor" href="#什么下会使用包装类-自动拆装箱了解吗-常量池技术是否清楚。" aria-label="Permalink to &quot;什么下会使用包装类，自动拆装箱了解吗，常量池技术是否清楚。&quot;">​</a></h4><h4 id="值传递和引用传递" tabindex="-1">值传递和引用传递 <a class="header-anchor" href="#值传递和引用传递" aria-label="Permalink to &quot;值传递和引用传递&quot;">​</a></h4><ul><li>值传递 <ul><li>是对基本数据类型⽽⾔，只进⾏值的拷⻉，不会影响原变量</li></ul></li><li>引用传递 <ul><li>对对象⽽⾔，不是传递对象的值，⽽是传递对象的地址， 如果副本改变会影响到原对象</li></ul></li></ul><h4 id="string-为什么是不可变的" tabindex="-1">String 为什么是不可变的 <a class="header-anchor" href="#string-为什么是不可变的" aria-label="Permalink to &quot;String 为什么是不可变的&quot;">​</a></h4><h4 id="final、finally、finalize-的区别" tabindex="-1">final、finally、finalize 的区别 <a class="header-anchor" href="#final、finally、finalize-的区别" aria-label="Permalink to &quot;final、finally、finalize 的区别&quot;">​</a></h4><h4 id="string、stringbuffer、stringbuilder-的区别" tabindex="-1">String、StringBuffer、StringBuilder 的区别 <a class="header-anchor" href="#string、stringbuffer、stringbuilder-的区别" aria-label="Permalink to &quot;String、StringBuffer、StringBuilder 的区别&quot;">​</a></h4><h4 id="包装类型的常量池技术了解吗。" tabindex="-1">包装类型的常量池技术了解吗。 <a class="header-anchor" href="#包装类型的常量池技术了解吗。" aria-label="Permalink to &quot;包装类型的常量池技术了解吗。&quot;">​</a></h4><ul><li>常量池技术是包装类型的一种缓存技术，能够减少对象的创建和内存使用，当数据的值在一个范围中，比如 Integer 对应的创建值在 -128 - 127；那么这个时候 Java 会从常量池中返回已存在的对象而不是创建一个新的对象。</li></ul><h4 id="包装类型和基础数据类型的区别" tabindex="-1">包装类型和基础数据类型的区别 <a class="header-anchor" href="#包装类型和基础数据类型的区别" aria-label="Permalink to &quot;包装类型和基础数据类型的区别&quot;">​</a></h4><ul><li>为什么要有包装类型 <ul><li>包装类型是对象类型，能够在Java 使用一些对象特性，比如参与到集合类、泛型、序列化等</li><li>另外包装类型是允许空值的，他在一些场景下用于区分“无数据”和“零值”时 是非常有用的；</li></ul></li><li>区别 <ul><li>内存分配不同：基础数据类型 → 栈；包装类型 → 堆；</li><li>默认值不同：比如 int → 0； Integer → null</li><li>内存占用、使用场景、性能会有一些差别。</li></ul></li></ul><h4 id="自动拆装箱的原理" tabindex="-1">自动拆装箱的原理 <a class="header-anchor" href="#自动拆装箱的原理" aria-label="Permalink to &quot;自动拆装箱的原理&quot;">​</a></h4><ul><li>自动拆装箱 <ul><li>自动拆箱：将 包装类 自动转换为基本数据类型</li><li>自动装箱：将 基本数据类型 转换为 包装类</li></ul></li><li>原理 <ul><li>装箱：通过调用包装类的 valueOf 方法</li><li>拆箱：通过调用包装类的 xxxValue 方法</li></ul></li></ul><h4 id="遇到过自动拆箱引发的-npe-问题吗" tabindex="-1">遇到过自动拆箱引发的 NPE 问题吗 <a class="header-anchor" href="#遇到过自动拆箱引发的-npe-问题吗" aria-label="Permalink to &quot;遇到过自动拆箱引发的 NPE 问题吗&quot;">​</a></h4><ul><li>什么情况下遇到：当 包装类型的引用为<code>null</code>，自动拆箱会触发 NPE</li><li>解决：尽量使用空值或者默认值的方式避免</li></ul><h4 id="switch-case-支持哪几种数据类型" tabindex="-1">switch case 支持哪几种数据类型 <a class="header-anchor" href="#switch-case-支持哪几种数据类型" aria-label="Permalink to &quot;switch case 支持哪几种数据类型&quot;">​</a></h4><ul><li><strong>整数类型</strong>、枚举类型、字符串</li></ul><h4 id="什么是值传递和引用传递" tabindex="-1">什么是值传递和引⽤传递 <a class="header-anchor" href="#什么是值传递和引用传递" aria-label="Permalink to &quot;什么是值传递和引⽤传递&quot;">​</a></h4><ul><li>值传递是对基本数据类型⽽⾔，<strong>只进⾏值的拷⻉</strong>，不会影响原变量</li><li>引⽤传递是对对象⽽⾔，不是传递对象的值，<strong>⽽是传递对象的地址</strong>， 如果副本改变会影响到原对象</li></ul><h4 id="final、finally、finalize的区别" tabindex="-1">final、finally、finalize的区别 <a class="header-anchor" href="#final、finally、finalize的区别" aria-label="Permalink to &quot;final、finally、finalize的区别&quot;">​</a></h4><ul><li>final修饰的类不能被继承、属性是常量⽽且必须初始化、修饰的⽅法 不能被重写</li><li>finally⽤于异常处理，finally代码块中的内容⼀定会执⾏</li><li>finalize是Object类的⼀个⽅法，当我们调⽤system.gc()时会调⽤，也 可以使⽤它在GC时⾃救⼀次 <ul><li>重写finalize⽅法的对象会被加⼊到⼀个 unfinalized 链表中，⾸次 GC时不会回收该对象，调⽤完finalize后，然后从unfinalized链表 剔除，此时对象可以进⾏⾃救，将⾃⼰重新加⼊到引⽤链上，下 ⼀次GC时会进⾏回收</li></ul></li></ul><hr><blockquote><p>关于对 finialize 的解释：</p></blockquote><p>Java中<code>finalize()</code>方法的工作原理以及 finalize 方法 与垃圾回收（GC）过程的关系</p><ul><li><code>finalize()</code>方法是<code>java.lang.Object</code>类的一个方法，Java允许子类重写这个方法，以实现资源的清理工作，比如关闭文件句柄或者释放网络资源等。</li><li>不过，需要注意的是，从Java 9开始，<code>finalize()</code>方法已被标记为废弃（deprecated），因为它的使用是不推荐的，主要因为它的不确定性、低效率和可能导致的内存泄露问题。</li></ul><p>以下是<code>finalize()</code>方法工作机制的详细解释：</p><ol><li><strong>重写<code>finalize()</code>方法的对象被加入到一个<code>unfinalized</code>链表中</strong>：当一个对象重写了<code>finalize()</code>方法，且该对象变成了垃圾（即没有任何强引用指向它），JVM就会将这个对象加入到一个专门的列表（称为<code>unfinalized</code>链表）中。这意味着，尽管这个对象已经没有被任何强引用指向，但因为重写了<code>finalize()</code>方法，它在第一次垃圾回收时不会立即被清理。</li><li><strong>首次GC时不会回收该对象</strong>：当垃圾回收器运行时，它会检测到<code>unfinalized</code>链表中的对象。对于这些对象，垃圾回收器不会直接回收它们，而是先调用它们的<code>finalize()</code>方法，目的是给这些对象一个清理资源的机会。</li><li><strong>调用完<code>finalize()</code>后，从<code>unfinalized</code>链表剔除</strong>：一旦对象的<code>finalize()</code>方法被调用，不论这个方法内部做了什么（即使是空操作），该对象会被从<code>unfinalized</code>链表中移除。此时，如果对象没有在其<code>finalize()</code>方法中重新被引用（即所谓的“自救”），它就会在下一次垃圾回收时被清理。</li><li><strong>对象可以进行自救</strong>：在<code>finalize()</code>方法执行期间，对象有机会将自己“自救”，即在方法内部使自己重新被引用（比如，将自己赋值给某个类变量或者对象的静态变量）。这样做可以阻止对象被垃圾回收器在当前回收周期内清理。</li><li><strong>下一次GC时会进行回收</strong>：如果对象在执行<code>finalize()</code>方法后没有进行自救，或者已经是第二次触发垃圾回收（即已经调用过<code>finalize()</code>方法），则在下一次垃圾回收时，这个对象将被彻底回收。</li></ol><p>需要强调的是，虽然<code>finalize()</code>方法提供了一种机制让对象在被回收前有机会清理资源，但由于它的不确定性和执行成本，以及可能导致的问题（如对象自救导致的内存泄露），在实际编程中应避免使用。</p><p>Java提供了其他资源管理机制，如<code>try-with-resources</code>语句和<code>AutoCloseable</code>接口，这些机制应该被优先考虑用于资源的清理。</p><p>一个简单的自救示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class SelfRescueDemo {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 用于保存对象的引用，以实现&quot;自救&quot;</span></span>
<span class="line"><span>    public static SelfRescueDemo rescueInstance = null;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    protected void finalize() throws Throwable {</span></span>
<span class="line"><span>        super.finalize();</span></span>
<span class="line"><span>        System.out.println(&quot;finalize method executed!&quot;);</span></span>
<span class="line"><span>        // 自救操作：将this赋值给rescueInstance</span></span>
<span class="line"><span>        SelfRescueDemo.rescueInstance = this;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static void main(String[] args) throws InterruptedException {</span></span>
<span class="line"><span>        rescueInstance = new SelfRescueDemo();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 第一次尝试自救</span></span>
<span class="line"><span>        rescueInstance = null; // 取消引用</span></span>
<span class="line"><span>        System.gc(); // 提示JVM进行垃圾回收</span></span>
<span class="line"><span>        Thread.sleep(500); // 留出时间给垃圾回收器执行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if (rescueInstance != null) {</span></span>
<span class="line"><span>            System.out.println(&quot;First rescue successful!&quot;);</span></span>
<span class="line"><span>        } else {</span></span>
<span class="line"><span>            System.out.println(&quot;First rescue failed.&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 第二次尝试自救</span></span>
<span class="line"><span>        rescueInstance = null; // 再次取消引用</span></span>
<span class="line"><span>        System.gc(); // 再次提示JVM进行垃圾回收</span></span>
<span class="line"><span>        Thread.sleep(500); // 再次留出时间给垃圾回收器执行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if (rescueInstance != null) {</span></span>
<span class="line"><span>            System.out.println(&quot;Second rescue successful!&quot;);</span></span>
<span class="line"><span>        } else {</span></span>
<span class="line"><span>            System.out.println(&quot;Second rescue failed. Object has been collected.&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个示例中，<code>SelfRescueDemo</code>类重写了<code>finalize()</code>方法，并在其中实现了自救逻辑。当<code>rescueInstance</code>对象第一次变为垃圾时，垃圾回收器会调用它的<code>finalize()</code>方法，在这个方法中，对象把自己的引用赋给了静态变量<code>rescueInstance</code>，从而达到了自救的目的。在第一轮垃圾回收后，我们可以看到打印出了&quot;finalize method executed!&quot;和&quot;First rescue successful!&quot;，说明对象成功自救。</p><p>然而，值得注意的是，任何对象的<code>finalize()</code>方法只会被系统自动调用一次。如果对象在完成首次自救后再次变成无引用状态，垃圾回收器在下一次回收时不会再次调用它的<code>finalize()</code>方法，这次对象将被直接回收。因此，在第二次设置<code>rescueInstance</code>为<code>null</code>并触发垃圾回收后，会打印出&quot;Second rescue failed. Object has been collected.&quot;，表示对象没有被再次自救，已经被回收。</p><p>这个示例展示了对象自救的概念和局限性。然而，在实际开发中，依赖<code>finalize()</code>方法进行资源清理或自救是不推荐的做法，因为它的执行时间是不确定的，而且可能导致资源释放不及时或者其他问题。使用Java提供的其他资源管理机制，如<code>try-with-resources</code>语句，是一种更好的做法。</p><h3 id="string" tabindex="-1">String <a class="header-anchor" href="#string" aria-label="Permalink to &quot;String&quot;">​</a></h3><h4 id="string为什么是不可变的" tabindex="-1">String为什么是不可变的 <a class="header-anchor" href="#string为什么是不可变的" aria-label="Permalink to &quot;String为什么是不可变的&quot;">​</a></h4><ul><li>String内部维护的是private final char/byte数组，<strong>不可变线程安全</strong></li><li>好处 <ul><li>防⽌被恶意篡改</li><li>作为HashMap的key可以保证不可变性</li><li>可以实现字符串常量池，在Java中，创建字符串对象的⽅式 <ul><li>通过字符串常量进⾏创建 <ul><li>在字符串常量池判断是否存在，如果存在就返回，不存 在就在字符串常量池创建后返回</li></ul></li><li>通过new字符串对象进⾏创建 <ul><li>在字符串常量池中判断是否存在，<strong>如果不存在就创建</strong>， 再判断堆中是否存在，如果不存在就创建，然后返回该 对象，总之要<strong>保证字符串常量池和堆中都有该对象</strong></li></ul></li></ul></li></ul></li></ul><p>可以讲一下为什么是不可变的，然后讲一下这样做有什么好处。</p><h4 id="string、stringbuffer、stringbuilder-的区别-1" tabindex="-1">String、StringBuffer、StringBuilder 的区别 <a class="header-anchor" href="#string、stringbuffer、stringbuilder-的区别-1" aria-label="Permalink to &quot;String、StringBuffer、StringBuilder 的区别&quot;">​</a></h4><ul><li>String: 不可变，线程安全 <ul><li>内部维护的是private final char/byte数组（不可变）</li></ul></li><li>StringBuilder：可变字符串，线程不安全；可以使⽤append进⾏拼接字符串</li><li>StringBuffer：可变字符串，线程安全；通过synchronized来保证线程安全，操作和 StringBuilder⼀样 <ul><li>synchronized对于出现在循环中会进⾏<strong>锁粗化</strong>，会将锁的范围扩 展到整个操作，从⽽避免频繁进⾏锁操作造成性能开销</li></ul></li></ul><p>String → StringBuffer → Synchronized → 锁粗化</p><h4 id="stringbuffer、stringbuilder-默认容量大小。" tabindex="-1">StringBuffer、StringBuilder 默认容量大小。 <a class="header-anchor" href="#stringbuffer、stringbuilder-默认容量大小。" aria-label="Permalink to &quot;StringBuffer、StringBuilder 默认容量大小。&quot;">​</a></h4><p>两个的默认容量大小都是 16 字符。</p><h4 id="string-字符串如何实现编码转换。" tabindex="-1">String 字符串如何实现编码转换。 <a class="header-anchor" href="#string-字符串如何实现编码转换。" aria-label="Permalink to &quot;String 字符串如何实现编码转换。&quot;">​</a></h4><p>一般是两个步骤：1. 将字符串转换为 byte 字节数组；2. 然后再将字节数组转换为字符串</p><h3 id="面向对象" tabindex="-1">面向对象 <a class="header-anchor" href="#面向对象" aria-label="Permalink to &quot;面向对象&quot;">​</a></h3><h4 id="面向对象和面向过程的区别" tabindex="-1">面向对象和面向过程的区别 <a class="header-anchor" href="#面向对象和面向过程的区别" aria-label="Permalink to &quot;面向对象和面向过程的区别&quot;">​</a></h4><ul><li>⾯向过程可以理解为按步骤处理问题</li><li>⾯向对象可以理解为将具体事务存在的属性、⾏为抽象出来，然后去 进⾏实现</li></ul><h4 id="封装、继承和多态" tabindex="-1">封装、继承和多态 <a class="header-anchor" href="#封装、继承和多态" aria-label="Permalink to &quot;封装、继承和多态&quot;">​</a></h4><ul><li><strong>封装</strong>：隐藏对象的细节和复杂性，同时提供公共的访问方法。封装通过访问控制保护了对象的状态。</li><li><strong>继承</strong>：允许新的类继承现有类的属性和方法。支持代码复用，并建立了类之间的层次关系。</li><li><strong>多态</strong>：允许使用统一的接口来表示不同的基础形态。同一个操作可应用于不同的对象，对象在运行时确定执行哪个方法。</li></ul><h4 id="字符串工具类-isempty-和-isblank-的区别" tabindex="-1">字符串工具类 isEmpty 和 isBlank 的区别 <a class="header-anchor" href="#字符串工具类-isempty-和-isblank-的区别" aria-label="Permalink to &quot;字符串工具类 isEmpty 和 isBlank 的区别&quot;">​</a></h4><ul><li>isEmpty 方法会检查字符串是否为 null 以及长度为 0 ;isEmpty(&quot; &quot;) → false</li><li>isBlank 方法会检查字符串是否为 null 以及是否是空字符串; isBlank(&quot; &quot;) → true</li></ul><h4 id="object-有哪些常用方法" tabindex="-1">Object 有哪些常用方法 <a class="header-anchor" href="#object-有哪些常用方法" aria-label="Permalink to &quot;Object 有哪些常用方法&quot;">​</a></h4><ul><li>equals、hashCode、toString、clone、finalize、wait、notify、notifyall</li><li>getClass()</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240320153706.png" alt="image.png"></p><h4 id="equals方法和-操作符的区别" tabindex="-1">equals方法和== 操作符的区别 <a class="header-anchor" href="#equals方法和-操作符的区别" aria-label="Permalink to &quot;equals方法和== 操作符的区别&quot;">​</a></h4><ul><li>== 操作符： <ul><li>基本数据类型：比较的是值是否相等。</li><li>对象类型：比较的是引用是否相同，即两个引用是否指向堆内存中的同一个位置。</li></ul></li><li><strong>equals方法</strong>： <ul><li>默认行为是比较对象在堆内存中的地址（与 == 相同）。</li><li>许多类（如String、Integer）重写了<code>.equals()</code>方法，使其用于比较对象的内容是否相等。</li></ul></li></ul><h4 id="equals-和-hashcode-的区别和联系。" tabindex="-1">equals 和 hashCode 的区别和联系。 <a class="header-anchor" href="#equals-和-hashcode-的区别和联系。" aria-label="Permalink to &quot;equals 和 hashCode 的区别和联系。&quot;">​</a></h4><ul><li>equals 一般用于比较两个对象的内容或状态是否相等，他默认的用法和 == 相同，如果是引用类型，会比较对象的引用地址；多数类会重写该方法，从而比较对象的内容而不是内存地址。</li><li>hashCode() 的作用是获取哈希码，即该对象在哈希表中的索引位置。哈希值在一些集合如HashMap、HashSet等非常关键</li><li>一般是建议重写 equals() 时必须重写 hashCode() 方法，如果没有重写哈希函数的话，两个键获取哈希表位置索引可能会不对，导致数据访问上的问题</li></ul><h4 id="两个对象的hashcode相同-equals一定相同吗" tabindex="-1">两个对象的hashcode相同，equals⼀定相同吗 <a class="header-anchor" href="#两个对象的hashcode相同-equals一定相同吗" aria-label="Permalink to &quot;两个对象的hashcode相同，equals⼀定相同吗&quot;">​</a></h4><ul><li>⼀般推荐重写equals⽅法的同时也要重写hashcode⽅法 <ul><li>两个对象的hashcode相同，equals可能相同</li><li>两个对象equals相同，hashcode⼀定相同</li></ul></li></ul><h4 id="hashcode的作用" tabindex="-1">Hashcode的作用 <a class="header-anchor" href="#hashcode的作用" aria-label="Permalink to &quot;Hashcode的作用&quot;">​</a></h4><p>java的集合有两类，一类是List，还有一类是Set。</p><p>前者有序可重复，后者无序不重复。当我们在set 中插入的时候怎么判断是否已经存在该元素呢，可以通过equals方法。但是如果元素太多，用这样 的方法就会比较慢。 于是有人发明了哈希算法来提高集合中查找元素的效率。 这种方式将集合分成若干个存储区域，每 个对象可以计算出一个哈希码，可以将哈希码分组，每组分别对应某个存储区域，根据一个对象的 哈希码就可以确定该对象应该存储的那个区域。</p><p>hashCode 方法可以这样理解：它返回的就是根据对象的内存地址换算出的一个值。这样一来，当 集合要添加新的元素时，先调用这个元素的hashCode方法，就一下子能定位到它应该放置的物理 位置上。如果这个位置上没有元素，它就可以直接存储在这个位置上，不用再进行任何比较了；如 果这个位置上已经有元素了，就调用它的equals方法与新元素进行比较，相同的话就不存了，不相 同就散列其它的地址。这样一来实际调用equals方法的次数就大大降低了，几乎只需要一两次</p><p>【hashcode() 哈希值 → equal 比较值 （提高索引效率）】</p><h4 id="重载和重写的区别" tabindex="-1">重载和重写的区别 <a class="header-anchor" href="#重载和重写的区别" aria-label="Permalink to &quot;重载和重写的区别&quot;">​</a></h4><ul><li>重写：<strong>子类重写父类的方法</strong>，返回类型、参数列表、方法名称相同 <ul><li>1.发生<strong>在父类与子类之间</strong></li><li>2.方法名，参数列表，返回类型（除过子类中方法的返回类型 是父类中返回类型的子类）必须相同</li><li>3.访问修饰符的限制一定要大于被重写方法的访问修饰符 （public&gt;protected&gt;default&gt;private)</li><li>4.重写方法一定不能抛出新的检查异常或者比被重写方法申 明更加宽泛的检查型异常</li></ul></li><li>重载：<strong>同一个类下</strong>，多个同名方法，参数列表不同; 方法返回值和访问修饰符可以不同 <ul><li>1.重载Overload是一个类中多态性的一种表现</li><li>2.重载要求同名方法的参数列表不同(参 数类型，参数个数甚至是参数顺序)</li><li>3.重载的时候，返回值类型可以相同也可以不相同。无法以返回 型别作为重载函数的区分标准</li></ul></li></ul><h3 id="类" tabindex="-1">类 <a class="header-anchor" href="#类" aria-label="Permalink to &quot;类&quot;">​</a></h3><h4 id="讲一下内部类-匿名内部类怎么使用的" tabindex="-1">讲一下内部类，匿名内部类怎么使用的 <a class="header-anchor" href="#讲一下内部类-匿名内部类怎么使用的" aria-label="Permalink to &quot;讲一下内部类，匿名内部类怎么使用的&quot;">​</a></h4><ul><li>在Java 中，内部类是定义在一个类内部的类，常用的内部类有：局部内部类、匿名内部类、静态内部类、成员内部类</li><li>匿名内部类的使用：继承一个父类或实现一个接口，实现其方法，然后调用这个方法；一般使用的常见场景有Thread类的匿名内部类实现和Runable 接口的匿名内部类实现。</li></ul><h4 id="讲一下深拷贝、浅拷贝和引用拷贝" tabindex="-1">讲一下深拷贝、浅拷贝和引用拷贝 <a class="header-anchor" href="#讲一下深拷贝、浅拷贝和引用拷贝" aria-label="Permalink to &quot;讲一下深拷贝、浅拷贝和引用拷贝&quot;">​</a></h4><ul><li>浅拷贝：只复制对象的基本类型字段和引用类型字段的引用，不复制引用对象本身。 <ul><li>副本对象和原对象都指向同⼀块内存空间，副本对象的改 变会影响到原对象</li></ul></li><li>深拷贝：复制对象的所有字段，包括基本类型和引用类型字段，引用类型的对象也会被复制。 <ul><li>副本对象和原对象不指向通⼀块内存空间，会重新开辟⼀ 块内存空间给副本对象进⾏指向</li></ul></li><li>引用拷贝：只复制对象的引用，不复制对象本身。</li></ul><h4 id="接口和抽象类的区别" tabindex="-1">接口和抽象类的区别 <a class="header-anchor" href="#接口和抽象类的区别" aria-label="Permalink to &quot;接口和抽象类的区别&quot;">​</a></h4><ul><li>首先是类和接口的区别，接口可以实现多个接口，类只能继承单个；</li><li>然后更多的是用法上面的区别：接口是一个协议，强调功能的相似性（相同的行为）；抽闲类强调的是类之间的共性（公共类结构）。</li></ul><h3 id="异常、反射、注解、泛型" tabindex="-1">异常、反射、注解、泛型 <a class="header-anchor" href="#异常、反射、注解、泛型" aria-label="Permalink to &quot;异常、反射、注解、泛型&quot;">​</a></h3><h4 id="讲一下空指针异常-如何避免" tabindex="-1">讲一下空指针异常，如何避免 <a class="header-anchor" href="#讲一下空指针异常-如何避免" aria-label="Permalink to &quot;讲一下空指针异常，如何避免&quot;">​</a></h4><ul><li>当我们在尝试使用 null 引用的时候，会发生 NPE</li><li>避免空指针异常 <ul><li><ol><li>在使用之前先检查一下是否为 null</li></ol></li><li><ol start="2"><li>调用方法的时候进行参数检查</li></ol></li><li><ol start="3"><li>在设计方法或者API 的时候，尽量不要返回 null 值，而且返回一个空集合或者默认值；</li></ol></li><li><ol start="4"><li>初始化使用字段，保证不为 null</li></ol></li><li><ol start="5"><li>使用 Optional</li></ol></li><li><ol start="6"><li>使用断言（开发和测试环境）</li></ol></li></ul></li></ul><h4 id="try-catch-finally-中哪个部分可以省略。" tabindex="-1">try-catch-finally 中哪个部分可以省略。 <a class="header-anchor" href="#try-catch-finally-中哪个部分可以省略。" aria-label="Permalink to &quot;try-catch-finally 中哪个部分可以省略。&quot;">​</a></h4><ul><li>可以省略<code>catch</code>块或<code>finally</code>块中的任何一个，但不能两个都省略</li></ul><h4 id="讲一下java-反射" tabindex="-1">讲一下Java 反射 <a class="header-anchor" href="#讲一下java-反射" aria-label="Permalink to &quot;讲一下Java 反射&quot;">​</a></h4><ul><li>反射：允许程序在运行时检查或修改Java虚拟机中的类</li><li>比如在框架中就大量使用动态代理获取到类的属性，从而实现一些复杂的功能。</li></ul><h4 id="讲一下-java-泛型" tabindex="-1">讲一下 Java 泛型 <a class="header-anchor" href="#讲一下-java-泛型" aria-label="Permalink to &quot;讲一下 Java 泛型&quot;">​</a></h4><p>泛型比较大的作用是能够提高代码重用性和灵活性；它允许在类、接口、方法上使用类型参数</p><h4 id="java-泛型中的-t、r、k、v、e-是什么。" tabindex="-1">Java 泛型中的 T、R、K、V、E 是什么。 <a class="header-anchor" href="#java-泛型中的-t、r、k、v、e-是什么。" aria-label="Permalink to &quot;Java 泛型中的 T、R、K、V、E 是什么。&quot;">​</a></h4><ul><li><code>T</code> - Type</li><li><code>R</code> - Return</li><li><code>K</code> - Key</li><li><code>V</code> - Value</li><li><code>E</code> - Element</li></ul><h3 id="spi" tabindex="-1">SPI <a class="header-anchor" href="#spi" aria-label="Permalink to &quot;SPI&quot;">​</a></h3><h4 id="什么是-spi-有什么用。" tabindex="-1">什么是 SPI，有什么用。 <a class="header-anchor" href="#什么是-spi-有什么用。" aria-label="Permalink to &quot;什么是 SPI，有什么用。&quot;">​</a></h4><p>Java 通过 SPI 机制为服务标准接口找到其实现服务。</p><h4 id="java-spi-实现原理了解吗。" tabindex="-1">Java SPI 实现原理了解吗。 <a class="header-anchor" href="#java-spi-实现原理了解吗。" aria-label="Permalink to &quot;Java SPI 实现原理了解吗。&quot;">​</a></h4><ul><li>Java SPI的实现基于<code>ServiceLoader</code>类。</li><li>服务提供者在<code>META-INF/services</code>目录下提供配置文件，其中指定接口的实现类。</li><li><code>ServiceLoader</code>可以加载这些实现。</li></ul><h3 id="io" tabindex="-1">IO <a class="header-anchor" href="#io" aria-label="Permalink to &quot;IO&quot;">​</a></h3><h4 id="i-o-流为什么要分为字节流和字符流呢" tabindex="-1">I/O 流为什么要分为字节流和字符流呢？ <a class="header-anchor" href="#i-o-流为什么要分为字节流和字符流呢" aria-label="Permalink to &quot;I/O 流为什么要分为字节流和字符流呢？&quot;">​</a></h4><ul><li>字节流：处理原始二进制数据</li><li>字符流：处理字符数据，自动处理字符编码问题</li></ul><h4 id="java-io-中的设计模式有哪些。" tabindex="-1">Java IO 中的设计模式有哪些。 <a class="header-anchor" href="#java-io-中的设计模式有哪些。" aria-label="Permalink to &quot;Java IO 中的设计模式有哪些。&quot;">​</a></h4><ul><li>装适器、适配器</li></ul><h4 id="常见的-io-模型有哪些" tabindex="-1">常见的 IO 模型有哪些 <a class="header-anchor" href="#常见的-io-模型有哪些" aria-label="Permalink to &quot;常见的 IO 模型有哪些&quot;">​</a></h4><ul><li>BIO（Blocking IO）：同步阻塞IO</li><li>NIO（Non-blocking IO）：同步非阻塞IO</li><li>AIO（Asynchronous IO）：异步非阻塞IO</li></ul><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><h4 id="java-怎么获取当前的系统时间戳" tabindex="-1">Java 怎么获取当前的系统时间戳 <a class="header-anchor" href="#java-怎么获取当前的系统时间戳" aria-label="Permalink to &quot;Java 怎么获取当前的系统时间戳&quot;">​</a></h4><ul><li>获取当前系统时间戳：<code>System.currentTimeMillis()</code></li></ul><p>如果需要 统计一段代码的耗时，可以使用上述方法获取执行方法前后的时间差。</p>`,108)])])}const f=l(s,[["render",t]]);export{p as __pageData,f as default};
